{
  "states": [
    "CLOSED",
    "LISTEN",
    "SYN-SENT",
    "SYN-RECEIVED",
    "ESTABLISHED",
    "FIN-WAIT-1",
    "FIN-WAIT-2",
    "CLOSE-WAIT",
    "CLOSING",
    "LAST-ACK",
    "TIME-WAIT"
  ],
  "transitions": [
    {
      "from": "CLOSED",
      "event": "OPEN (passive)",
      "action": "create TCB, enter LISTEN state",
      "to": "LISTEN"
    },
    {
      "from": "CLOSED",
      "event": "OPEN (active)",
      "action": "select ISS, send SYN, enter SYN-SENT state",
      "to": "SYN-SENT"
    },
    {
      "from": "LISTEN",
      "event": "OPEN (active)",
      "action": "change to active, select ISS, send SYN, enter SYN-SENT state",
      "to": "SYN-SENT"
    },
    {
      "from": "LISTEN",
      "event": "rcv SYN",
      "action": "set RCV.NXT, IRS, select ISS, send SYN+ACK, enter SYN-RECEIVED state",
      "to": "SYN-RECEIVED"
    },
    {
      "from": "LISTEN",
      "event": "rcv ACK",
      "action": "send RST",
      "to": "LISTEN"
    },
    {
      "from": "LISTEN",
      "event": "rcv RST",
      "action": "ignore",
      "to": "LISTEN"
    },
    {
      "from": "SYN-SENT",
      "event": "rcv SYN+ACK",
      "action": "set variables, send ACK, enter ESTABLISHED state",
      "to": "ESTABLISHED"
    },
    {
      "from": "SYN-SENT",
      "event": "rcv SYN",
      "action": "enter SYN-RECEIVED state",
      "to": "SYN-RECEIVED"
    },
    {
      "from": "SYN-SENT",
      "event": "rcv ACK (acceptable)",
      "action": "discard segment",
      "to": "SYN-SENT"
    },
    {
      "from": "SYN-SENT",
      "event": "rcv RST",
      "action": "signal error, delete TCB, enter CLOSED state",
      "to": "CLOSED"
    },
    {
      "from": "SYN-RECEIVED",
      "event": "rcv ACK (acceptable)",
      "action": "enter ESTABLISHED state",
      "to": "ESTABLISHED"
    },
    {
      "from": "SYN-RECEIVED",
      "event": "rcv SYN+ACK",
      "action": "send RST, enter LISTEN state (if passive) or handle per synchronized states",
      "to": "LISTEN"
    },
    {
      "from": "SYN-RECEIVED",
      "event": "rcv RST",
      "action": "if passive: return to LISTEN; if active: signal error, enter CLOSED state",
      "to": "LISTEN"
    },
    {
      "from": "ESTABLISHED",
      "event": "CLOSE",
      "action": "form FIN segment, send it, enter FIN-WAIT-1 state",
      "to": "FIN-WAIT-1"
    },
    {
      "from": "ESTABLISHED",
      "event": "rcv FIN",
      "action": "enter CLOSE-WAIT state",
      "to": "CLOSE-WAIT"
    },
    {
      "from": "FIN-WAIT-1",
      "event": "rcv ACK of our FIN",
      "action": "enter TIME-WAIT state",
      "to": "TIME-WAIT"
    },
    {
      "from": "FIN-WAIT-1",
      "event": "rcv FIN",
      "action": "send ACK, enter CLOSING state",
      "to": "CLOSING"
    },
    {
      "from": "FIN-WAIT-2",
      "event": "CLOSE",
      "action": "acknowledge CLOSE (ok), do not delete TCB",
      "to": "FIN-WAIT-2"
    },
    {
      "from": "CLOSE-WAIT",
      "event": "CLOSE",
      "action": "send FIN, enter LAST-ACK state",
      "to": "LAST-ACK"
    },
    {
      "from": "CLOSING",
      "event": "rcv ACK of our FIN",
      "action": "enter TIME-WAIT state",
      "to": "TIME-WAIT"
    },
    {
      "from": "LAST-ACK",
      "event": "rcv ACK of our FIN",
      "action": "delete TCB, enter CLOSED state",
      "to": "CLOSED"
    },
    {
      "from": "TIME-WAIT",
      "event": "TIME-WAIT TIMEOUT",
      "action": "delete TCB, enter CLOSED state",
      "to": "CLOSED"
    }
  ]
}
